effect.shader:
vec4 tex2(vec2 p){ return texture2DCv(inputImg2.texture, p); }
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec2 uv = acScreenNorm;
vec4 a = tex(uv);
vec4 b = tex2(uv);
vec2 q = uv - vec2(0.5);
q.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
float ang = atan(q.y, q.x) / 6.28318530718 + 0.5;
float p = clamp(progress, 0.0, 1.0);
float soft = max(feather, 0.001);
float m = smoothstep(p - soft, p + soft, ang);
m = mix(m, 1.0 - m, clamp(reverse, 0.0, 1.0));
vec4 c = mix(b, a, m);
gl_FragColor = vec4(mix(a, c, mixAmt));
}
